<?php
namespace App\Http\Controllers\Configuration;
use App\Http\Controllers\Controller; use App\Models\DocumentSequence; use App\Services\Audit\ActivityLogService; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class DocumentSequenceController extends Controller { public function __construct(){ $this->middleware('menu.permission:config.numbering,view')->only('index');$this->middleware('menu.permission:config.numbering,create')->only(['create','store']);$this->middleware('menu.permission:config.numbering,edit')->only(['edit','update']); }
 public function index(){return view('configuration.numbering.index',['rows'=>DocumentSequence::orderBy('code')->get()]);} public function create(){return view('configuration.numbering.form',['record'=>new DocumentSequence(['prefix'=>'DOC','date_format'=>'ym','separator'=>'/','padding'=>5,'reset_period'=>'monthly','format_pattern'=>'DOC/{YY}{MM}/{#####}','is_active'=>true]),'isEdit'=>false]);}
 private function rules(?int $id=null): array{return ['code'=>['required','string','max:50',Rule::unique('document_sequences','code')->ignore($id)],'prefix'=>['required','string','max:30'],'date_format'=>['nullable','string','max:20'],'separator'=>['required','string','max:5'],'padding'=>['required','integer','min:1','max:12'],'format_pattern'=>['nullable','string','max:120','regex:/\{#+\}/'],'reset_period'=>['required','in:none,never,daily,monthly,yearly'],'is_active'=>['required','boolean']];}
 public function store(Request $r,ActivityLogService $audit){$m=DocumentSequence::create($r->validate($this->rules()));$audit->record('config.numbering','create',$m,[],$m->toArray());return redirect()->route('config.numbering.index')->with('success','Sequence created.');} public function edit(DocumentSequence $sequence){return view('configuration.numbering.form',['record'=>$sequence,'isEdit'=>true]);} public function update(Request $r,DocumentSequence $sequence,ActivityLogService $audit){$before=$sequence->toArray();$sequence->update($r->validate($this->rules($sequence->id)));$audit->record('config.numbering','update',$sequence,$before,$sequence->fresh()->toArray());return redirect()->route('config.numbering.index')->with('success','Sequence updated.');}
}
